public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds a reaction or a tag to a message. Use getMessageAvailableReactions to receive the list of available reactions for the message
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> AddMessageReactionAsync(long chatId = default, long messageId = default, ReactionType reactionType = default, bool isBig = default, bool updateRecentReactions = default)
    {

           using var activity =  StartCallActivity("AddMessageReactionAsync", typeof(AddMessageReaction).FullName ?? "AddMessageReactionAsync");

           try
           {
             return client.AddMessageReactionAsync(chatId, messageId, reactionType, isBig, updateRecentReactions);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
